def selectionProofEvenKeyCensus(readings, k):
    a=readings
    out=[]
    sums=set()
    def visit(i,s):
        if i==len(a):
            sums.add(s)
            return
        visit(i+1,s)
        visit(i+1,s+a[i])
    visit(0,0)
    out=sorted(sums)
    return sum(x%2==0 for x in out)

